const canvasShapesPlugin = {
  id: "canvasShapesPlugin",
  afterDraw(chart, args, pluginOptions) {
    if (!pluginOptions || !Array.isArray(pluginOptions.shapes)) return;
    const { ctx, scales } = chart;
    const xScale = scales.x;
    const yScale = scales.y;
    const x = (value) => xScale.getPixelForValue(value);
    const y = (value) => yScale.getPixelForValue(value);
    const dx = (value) => Math.abs(x(value) - x(0));
    const dy = (value) => Math.abs(y(value) - y(0));

    function applyStyle(shape) {
      ctx.lineWidth = shape.lineWidth ?? 1.5;
      ctx.strokeStyle = shape.stroke ?? "#000000";
      ctx.fillStyle = shape.fill ?? "rgba(0,0,0,0)";
      ctx.font = shape.font ?? "13px Arial";
      ctx.textAlign = shape.textAlign ?? "center";
      ctx.textBaseline = shape.textBaseline ?? "middle";
    }

    function drawArrowHead(x1, y1, x2, y2, size = 6) {
      const angle = Math.atan2(y2 - y1, x2 - x1);
      ctx.beginPath();
      ctx.moveTo(x2, y2);
      ctx.lineTo(x2 - size * Math.cos(angle - Math.PI / 6), y2 - size * Math.sin(angle - Math.PI / 6));
      ctx.moveTo(x2, y2);
      ctx.lineTo(x2 - size * Math.cos(angle + Math.PI / 6), y2 - size * Math.sin(angle + Math.PI / 6));
      ctx.stroke();
    }

    ctx.save();
    for (const shape of pluginOptions.shapes) {
      applyStyle(shape);

      if (shape.type === "circle") {
        ctx.beginPath();
        ctx.arc(x(shape.x), y(shape.y), dx(shape.r), 0, Math.PI * 2);
        if (shape.fill && shape.fill !== "transparent") ctx.fill();
        ctx.stroke();
      }

      if (shape.type === "rectangle") {
        const left = x(shape.x);
        const top = y(shape.y + shape.height);
        const width = x(shape.x + shape.width) - x(shape.x);
        const height = y(shape.y) - y(shape.y + shape.height);
        ctx.beginPath();
        ctx.rect(left, top, width, height);
        if (shape.fill && shape.fill !== "transparent") ctx.fill();
        ctx.stroke();
      }

      if (shape.type === "polygon") {
        ctx.beginPath();
        shape.points.forEach((point, index) => {
          const px = x(point[0]);
          const py = y(point[1]);
          if (index === 0) ctx.moveTo(px, py);
          else ctx.lineTo(px, py);
        });
        ctx.closePath();
        if (shape.fill && shape.fill !== "transparent") ctx.fill();
        ctx.stroke();
      }

      if (shape.type === "line") {
        ctx.beginPath();
        ctx.moveTo(x(shape.x1), y(shape.y1));
        ctx.lineTo(x(shape.x2), y(shape.y2));
        ctx.stroke();
      }

      if (shape.type === "dimensionLine") {
        const x1 = x(shape.x1);
        const y1 = y(shape.y1);
        const x2 = x(shape.x2);
        const y2 = y(shape.y2);
        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.stroke();
        if (shape.arrows !== false) {
          drawArrowHead(x2, y2, x1, y1, shape.arrowSize ?? 6);
          drawArrowHead(x1, y1, x2, y2, shape.arrowSize ?? 6);
        }
        if (shape.label) {
          ctx.fillStyle = shape.labelColor ?? shape.stroke ?? "#000000";
          ctx.fillText(shape.label, (x1 + x2) / 2, (y1 + y2) / 2 + (shape.labelOffsetY ?? -10));
        }
      }

      if (shape.type === "ellipseArc") {
        const centerX = x(shape.x);
        const centerY = y(shape.y);
        const radiusX = dx(shape.radiusX);
        const radiusY = dy(shape.radiusY);
        ctx.beginPath();
        ctx.ellipse(centerX, centerY, radiusX, radiusY, 0, shape.startAngle ?? 0, shape.endAngle ?? Math.PI, shape.anticlockwise ?? false);
        if (shape.closePath) {
          ctx.lineTo(x(shape.closeToX ?? (shape.x - shape.radiusX)), y(shape.closeToY ?? shape.y));
          ctx.closePath();
        }
        if (shape.fill && shape.fill !== "transparent") ctx.fill();
        ctx.stroke();
      }

      if (shape.type === "text") {
        ctx.fillStyle = shape.fill ?? "#000000";
        ctx.fillText(shape.text, x(shape.x), y(shape.y));
      }
    }
    ctx.restore();
  }
};
